import{V4_BUILD,loadState,saveState,resetV4FromV3,makeId,localDateKey,money,isArchived,archiveItem,restoreItem,upsertDebt,removeDebt,syncDebtFromBill,activeRows}from'./store.js';
import{processMochini,resolveClarification,rejectProposal,clearChat}from'./mochini.js';

const app=document.getElementById('app');
let state=loadState();
let view=state.v4?.ui?.lastView||'home';
let dialog=null;
let status='';
const list=v=>Array.isArray(v)?v:[];const obj=v=>v&&typeof v==='object'&&!Array.isArray(v)?v:{};const text=v=>String(v??'').trim();const clone=v=>structuredClone(v);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=v=>{if(!v)return'Any day';const d=new Date(`${String(v).slice(0,10)}T12:00:00`);return Number.isNaN(d.getTime())?v:d.toLocaleDateString([],{weekday:'short',month:'short',day:'numeric'})};
const fmtTime=v=>{if(!v)return'';const [h,m]=String(v).split(':').map(Number);if(!Number.isFinite(h))return v;const d=new Date();d.setHours(h,m||0,0,0);return d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})};
const currency=v=>money(v).toLocaleString([],{style:'currency',currency:'USD'});const today=()=>localDateKey();
const todayDate=()=>new Date(`${today()}T12:00:00`);const dayKey=d=>localDateKey(d);const addDays=(date,n)=>{const d=date instanceof Date?new Date(date):new Date(`${date}T12:00:00`);d.setDate(d.getDate()+n);return d};
const field=(label,html,wide='')=>`<label class="field ${wide?'wide':''}"><span>${esc(label)}</span>${html}</label>`;
const archiveBtn=(kind,id)=>`<button class="btn tiny" data-action="archive" data-kind="${esc(kind)}" data-id="${esc(id)}">📦 Archive</button>`;
const doneLike=x=>x?.done===true||x?.completed===true||['complete','completed','done'].includes(x?.status);
const priorityMeta=p=>({today:['🌸','Need to do today','priority-today'],soon:['🪴','Should do soon','priority-soon'],whenever:['🌿','Whenever','priority-whenever'],idea:['🌱','Idea','priority-idea']}[p]||['🌿','Whenever','priority-whenever']);
function taskPriority(t){if(['today','soon','whenever','idea'].includes(t.priority))return t.priority;if(t.date===today())return'today';if(t.date){const diff=(new Date(`${t.date}T12:00:00`)-todayDate())/86400000;if(diff<=3)return'soon'}return'whenever'}
function setStatus(msg){status=msg;setTimeout(()=>{if(status===msg){status='';render()}},2400)}
function persist(msg='Saved'){state=saveState(state);setStatus(`✓ ${msg}`);render()}
function setView(next){view=next;state.v4.ui={...state.v4.ui,lastView:next};state=saveState(state);dialog=null;window.scrollTo({top:0,behavior:'auto'});render()}
function setMode(mode){state.v4.mode=mode;state=saveState(state);render()}
function active(kind,rows){return activeRows(state,kind,rows)}
function archived(kind,id){return isArchived(state,kind,id)}

function scheduledMinutesOn(date){let total=0;for(const e of list(state.life.events)){if(e.date!==date||!e.startTime||!e.endTime)continue;const[a,b]=[e.startTime,e.endTime].map(t=>{const[h,m]=String(t).split(':').map(Number);return h*60+(m||0)});total+=Math.max(0,b-a)}for(const s of list(state.work.shifts)){if(s.date!==date||!s.startTime||!s.endTime)continue;const[a,b]=[s.startTime,s.endTime].map(t=>{const[h,m]=String(t).split(':').map(Number);return h*60+(m||0)});total+=Math.max(0,b-a)}return total}
function nextFlexibleDate(from=today()){for(let i=0;i<7;i++){const d=dayKey(addDays(from,i));if(scheduledMinutesOn(d)<=300)return d}return dayKey(addDays(from,1))}
function autoRollover(){if(state.v4.lastRolloverDate===today())return;let changed=false;state.life.tasks=list(state.life.tasks).map(t=>{if(t.done||t.protected||archived('task',t.id)||!t.date||t.date>=today())return t;changed=true;return{...t,date:nextFlexibleDate(today()),rolledFrom:t.date,rolledAt:new Date().toISOString()}});state.v4.lastRolloverDate=today();if(changed||true)state=saveState(state)}
autoRollover();

const NAV=[
 ['🏡 HOME',[['home','🏡','Home Sweet Home'],['time','📅','Berry Busy'],['tasks','📝','Sweet To-Dos'],['mochini','🍡','Mochini'],['pings','🔔','Little Pings'],['review','🌙','Day in Review']]],
 ['🍓 LIFE',[['routines','🔁','Routines'],['noms','🍱','Noms Nook'],['sips','💧','Sip Station'],['motion','🌿','Motion Meadow'],['people','💕','People & Plans'],['hobbies','🎨','Hobby Shelf']]],
 ['💼 WORK + MONEY',[['boss','💼','Boss Bitch'],['money','☕','Money Café'],['study','🎓','Study Nook'],['threads','🧵','Threads']]],
 ['✨ GROW + SYSTEM',[['growth','🌱','Growth Room'],['dump','🧠','Get It Outta My Head'],['admin','🗃️','Unfortunately, I’m an Adult'],['reset','🌸','Reset Lab'],['patterns','🔬','Pattern Lab'],['archive','📦','Memory Box'],['settings','🎀','V4 Settings']]]
];
function navHtml(){return NAV.map(([label,items])=>`<div class="nav-group"><div class="nav-label">${label}</div>${items.map(([id,icon,name])=>`<button class="nav-btn ${view===id?'active':''}" data-view="${id}"><span class="nav-icon">${icon}</span>${esc(name)}</button>`).join('')}</div>`).join('')}
function shell(content){const mode=state.v4.mode||'normal';document.body.classList.toggle('mode-tiny',mode==='tiny');document.body.classList.toggle('mode-power',mode==='power');return`<div class="katos"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-row"><div class="berry">🍓</div><div><h1>KatOS V4</h1><div class="scribble">pretty, smart, and nosy enough</div></div></div><div class="build">PREVIEW · ${V4_BUILD}</div></div><nav class="nav">${navHtml()}</nav><div class="sidebar-foot">V4 has its own data copy. V3 is untouched. 🔒<br><a href="../v3/" style="color:#b14f78;font-weight:800">Open V3 emergency exit</a></div></aside><header class="topbar"><button class="btn menu" data-action="menu">☰</button><div class="top-title">${esc(NAV.flatMap(x=>x[1]).find(x=>x[0]===view)?.[2]||'KatOS')}</div><div class="top-spacer"></div><div class="mode-switch"><button class="mode-btn ${mode==='normal'?'active':''}" data-mode="normal">🍓 <span>Normal</span></button><button class="mode-btn ${mode==='tiny'?'active':''}" data-mode="tiny">🫧 <span>Tiny</span></button><button class="mode-btn ${mode==='power'?'active':''}" data-mode="power">⚡ <span>Power</span></button></div></header><main class="main">${status?`<div class="note" style="margin-bottom:10px">${esc(status)}</div>`:''}${content}</main>${renderDialog()}</div>`}

function contextBits(){return[['brain','🧠'],['energy','⚡'],['capacity','🎀'],['pressure','⏰']].map(([k,i])=>`<span class="chip">${i} ${esc(state.context?.[k]||'')}</span>`).join('')}
function currentEnergyBlock(){const now=new Date(),mins=now.getHours()*60+now.getMinutes();return list(state.v4.energyBlocks).find(b=>{if(!b.start||!b.end)return false;const a=b.start.split(':').map(Number),z=b.end.split(':').map(Number);return mins>=a[0]*60+(a[1]||0)&&mins<z[0]*60+(z[1]||0)})||null}
function openDays(){const out=[];for(let i=1;i<=5;i++){const date=dayKey(addDays(today(),i)),events=list(state.life.events).filter(x=>x.date===date),shifts=list(state.work.shifts).filter(x=>x.date===date);if(!events.length&&!shifts.length)out.push(date)}return out}
function makeOpenDayPlan(date){const tasks=active('task',state.life.tasks).filter(t=>!t.done&&!t.protected&&(!t.date||t.date<=date)).slice(0,2);const hobby=active('hobby',state.v4.hobbies).find(h=>h.status==='playing')||active('hobby',state.v4.hobbies)[0];const move=active('motion-recipe',state.movement.routines).find(x=>!x.archived);const items=[...tasks.map(t=>({id:makeId('plan-item'),label:t.text||t.title,kind:'task',done:false})),...(hobby?[{id:makeId('plan-item'),label:`Fun thing: ${hobby.name}`,kind:'hobby',done:false}]:[]),...(move?[{id:makeId('plan-item'),label:`Move a little: ${move.name}`,kind:'motion',done:false}]:[])];state.v4.openDayPlans=[...list(state.v4.openDayPlans).filter(p=>p.date!==date),{id:makeId('open-day'),date,items,createdAt:new Date().toISOString()}];persist(`Made a soft plan for ${fmtDate(date)}`)}
function homeView(){const block=currentEnergyBlock(),open=openDays()[0],plan=list(state.v4.openDayPlans).find(p=>p.date===open),tasks=active('task',state.life.tasks).filter(t=>!t.done),pings=active('reminder',state.life.reminders).filter(x=>!x.completed),todayEvents=timeItemsFor(today()),next=todayEvents.find(x=>x.startTime&&x.startTime>=new Date().toTimeString().slice(0,5));const picks=rankTasks(tasks).slice(0,state.v4.mode==='tiny'?1:state.v4.mode==='power'?5:3);return`<div class="page"><section class="hero"><div class="ey">🏡 HOME SWEET HOME · V4</div><h2>${greeting()} ${state.v4.mode==='power'?'⚡':''}</h2><p>${block?`You’re in <b>${esc(block.name)}</b> right now. `:''}${state.v4.mode==='tiny'?'Tiny Mode is hiding the wallpaper-sized to-do list.':state.v4.mode==='power'?'Power Mode is front-loading the useful high-energy stuff, then we land softly.':'KatOS is showing what matters without inventing extra work.'}</p><div class="chip-row" style="margin-top:12px">${contextBits()}</div></section><div class="grid"><section class="card two-thirds"><div class="card-head"><div><div class="ey">✨ WHAT FITS RIGHT NOW?</div><h2>${picks.length?'The front row':'Nothing is demanding the stage'}</h2></div><div class="count">${picks.length}</div></div>${picks.length?`<div class="stack">${picks.map(taskRow).join('')}</div>`:`<div class="empty">Resting, hobbies, or doing absolutely nothing on purpose are all legal.</div>`}<div class="button-row" style="margin-top:11px"><button class="btn primary" data-view="mochini">🍡 Ask Mochini what to do</button><button class="btn" data-view="tasks">See all Sweet To-Dos</button></div></section><section class="card third"><div class="ey">📅 NEXT</div><h2>${next?esc(next.title):'The calendar is chill'}</h2><p>${next?`${esc(fmtTime(next.startTime))}${next.detail?` · ${esc(next.detail)}`:''}`:'No timed thing is waiting right now.'}</p>${pings.filter(x=>x.date===today()||x.timing==='before_bed').length?`<div class="callout" style="margin-top:10px">🔔 ${pings.filter(x=>x.date===today()||x.timing==='before_bed').length} Little Ping(s) still hanging around.</div>`:''}</section><section class="card full tiny-hide"><div class="card-head"><div><div class="ey">🌤️ OPEN DAY MAGIC</div><h2>${open?`${fmtDate(open)} is suspiciously empty`:'Your next few days already have structure'}</h2><p>KatOS can make a soft plan from flexible tasks, hobbies, and movement without turning your free day into unpaid labor.</p></div></div>${open?(plan?`<div class="stack">${plan.items.map(x=>`<div class="row grow"><div>✨</div><div><b>${esc(x.label)}</b><span class="meta">${esc(x.kind)}</span></div></div>`).join('')}</div><div class="button-row" style="margin-top:10px"><button class="btn" data-action="open-plan" data-date="${open}">Regenerate softer plan</button></div>`:`<button class="btn primary" data-action="open-plan" data-date="${open}">🧚 Plan this open day</button>`):''}</section><section class="card full tiny-hide"><div class="card-head"><div><div class="ey">🎀 YOUR ENERGY BLOCKS</div><h2>The day, in chunks your brain actually recognizes</h2></div></div><div class="stack">${list(state.v4.energyBlocks).map(b=>`<div class="row grow"><div>✨</div><div><b>${esc(b.name)}</b><span class="meta">${fmtTime(b.start)}–${fmtTime(b.end)} · ${esc(b.energy)} energy</span></div></div>`).join('')}</div><button class="btn" style="margin-top:10px" data-action="edit-blocks">Edit blocks</button></section></div></div>`}
function greeting(){const h=new Date().getHours();return h<11?'Good morning, Kat 🌸':h<17?'Good afternoon, Kat 💗':h<21?'Good evening, Kat ✨':'You made it through the day 🌙'}
function rankTasks(rows){const energy=state.context.energy,ceil=state.v4.mode==='power'?2:energy==='drained'?0:1;const er={low:0,medium:1,high:2};return rows.slice().sort((a,b)=>{const score=t=>{let n=0;if(t.protected)n+=90;if(t.date&&t.date<today())n+=45;if(t.date===today())n+=35;const p=taskPriority(t);n+=({today:30,soon:18,whenever:4,idea:-10}[p]||0);if((er[t.energy]??1)<=ceil)n+=20;else n-=20;if(state.v4.mode==='power'&&t.energy==='high')n+=18;if(Number(t.minutes||15)<=15)n+=7;return n};return score(b)-score(a)})}
function taskRow(t){const [icon,label,cls]=priorityMeta(taskPriority(t));return`<div class="row grow ${t.done?'done':''}"><button class="check" data-action="toggle-task" data-id="${esc(t.id)}">${t.done?'✓':'○'}</button><div><b>${esc(t.text||t.title)}</b><span class="meta"><span class="${cls}">${icon} ${label}</span>${t.date?` · ${esc(fmtDate(t.date))}`:''} · ${Number(t.minutes||15)}m · ${esc(t.energy||'medium')}${t.protected?' · 🔒 protected':''}${t.location?` · 📍 ${esc(t.location)}`:''}</span></div><div class="button-row"><button class="btn tiny" data-action="edit" data-kind="task" data-id="${esc(t.id)}">✏️</button>${archiveBtn('task',t.id)}<button class="btn tiny danger" data-action="delete" data-kind="task" data-id="${esc(t.id)}">×</button></div></div>`}

function tasksView(){const rows=active('task',state.life.tasks);return`<div class="page"><section class="hero"><div class="ey">📝 SWEET TO-DOS</div><h2>Things Future Me Will Be Glad I Did</h2><p>Priority is plant-coded, flexible stuff can roll to a better day, and protected means “no babe, actually do this.”</p></section><div class="grid"><section class="card full"><form data-form="task"><div class="fields">${field('Task','<input name="text" required placeholder="What needs doing?">',1)}${field('Priority',`<select name="priority"><option value="today">🌸 Need to do today</option><option value="soon">🪴 Should do soon</option><option value="whenever" selected>🌿 Whenever</option><option value="idea">🌱 Idea</option></select>`)}${field('Date · optional','<input name="date" type="date">')}${field('Time estimate',`<select name="minutes"><option>5</option><option selected>15</option><option>30</option><option>60</option></select>`)}${field('Energy',`<select name="energy"><option>low</option><option selected>medium</option><option>high</option></select>`)}${field('Location / room','<input name="location" placeholder="Kitchen, bedroom, errands…">')}${field('Protected?',`<select name="protected"><option value="false">Flexible</option><option value="true">🔒 No babe, actually do this</option></select>`)}</div><div class="form-actions"><button class="btn primary">＋ Add Sweet To-Do</button></div></form></section><section class="card full"><div class="card-head"><div><div class="ey">🌸 🪴 🌿 🌱</div><h2>Your actual list</h2></div><div class="count">${rows.filter(x=>!x.done).length}</div></div><div class="stack">${rows.length?rankTasks(rows).map(taskRow).join(''):'<div class="empty">Nothing here. Suspiciously peaceful.</div>'}</div></section></div></div>`}

function timeItemsFor(date){const out=[];for(const e of active('event',state.life.events))if(e.date===date)out.push({...e,source:'event',detail:e.type||'event'});for(const s of active('shift',state.work.shifts))if(s.date===date)out.push({id:s.id,title:s.label||'Work shift',date,startTime:s.startTime,endTime:s.endTime,source:'shift',detail:'Boss Bitch'});for(const t of active('task',state.life.tasks))if(!t.done&&t.date===date)out.push({id:t.id,title:t.text||t.title,date,source:'task',detail:'Sweet To-Do'});for(const r of active('reminder',state.life.reminders))if(!r.completed&&r.date===date)out.push({id:r.id,title:r.title,date,startTime:r.time,source:'ping',detail:'Little Ping'});for(const i of active('study-item',state.education.items))if(!i.done&&i.dueDate===date)out.push({id:i.id,title:i.title,date,startTime:i.dueTime,source:'study',detail:'Study Nook'});for(const b of active('bill',state.money.bills))if(!b.paid&&billDateFor(b)===date)out.push({id:b.id,title:b.name,date,source:'bill',detail:`${currency(b.amount)} · Shit I Don't Wanna Pay`});return out.sort((a,b)=>String(a.startTime||'99:99').localeCompare(String(b.startTime||'99:99')))}
function billDateFor(b){if(b.dueDate)return b.dueDate;if(b.dueDay){const d=new Date();d.setHours(12,0,0,0);let target=new Date(d.getFullYear(),d.getMonth(),Math.min(b.dueDay,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()),12);if(localDateKey(target)<today())target=new Date(d.getFullYear(),d.getMonth()+1,Math.min(b.dueDay,new Date(d.getFullYear(),d.getMonth()+2,0).getDate()),12);return localDateKey(target)}return''}
function timeView(){const start=addDays(todayDate(),-((todayDate().getDay()+6)%7)),days=Array.from({length:7},(_,i)=>addDays(start,i));return`<div class="page"><section class="hero"><div class="ey">📅 BERRY BUSY</div><h2>What time is doing to me this week</h2><p>One time surface, many source modules. Linked things stay owned by the room that created them.</p></section><section class="card full"><div class="calendar-strip">${days.map(d=>{const k=dayKey(d),items=timeItemsFor(k);return`<div class="day-box ${k===today()?'today':''}"><b>${d.toLocaleDateString([],{weekday:'short'})} ${d.getDate()}</b><small>${items.length} thing${items.length===1?'':'s'}</small>${items.slice(0,4).map(x=>`<div class="day-item">${x.startTime?`${fmtTime(x.startTime)} · `:''}${esc(x.title)}</div>`).join('')}</div>`}).join('')}</div></section><div class="grid"><section class="card"><div class="ey">＋ ADD TIME ITEM</div><h2>Only native time goes here</h2><form data-form="event"><div class="fields">${field('Title','<input name="title" required placeholder="Dentist appointment">',1)}${field('Type',`<select name="type"><option>event</option><option>appointment</option><option>time-block</option><option>deadline</option></select>`)}${field('Date',`<input name="date" type="date" required value="${today()}">`)}${field('Start · optional','<input name="startTime" type="time">')}${field('End · optional','<input name="endTime" type="time">')}${field('Location','<input name="location">')}</div><div class="form-actions"><button class="btn primary">＋ Add</button></div></form></section><section class="card"><div class="ey">📍 TODAY'S MAP</div><h2>Everything affecting today</h2><div class="stack">${timeItemsFor(today()).map(x=>`<div class="row grow"><div>${x.source==='bill'?'💸':x.source==='shift'?'💼':x.source==='task'?'📝':x.source==='ping'?'🔔':'📅'}</div><div><b>${esc(x.title)}</b><span class="meta">${x.startTime?fmtTime(x.startTime):'All day'} · ${esc(x.detail||x.source)}</span></div></div>`).join('')||'<div class="empty">The rest of today is open.</div>'}</div></section></div></div>`}

function pingsView(){const rows=active('reminder',state.life.reminders);return`<div class="page"><section class="hero"><div class="ey">🔔 LITTLE PINGS</div><h2>Remember this, but make it small</h2><p>Not every future thing deserves to become a task with emotional baggage.</p></section><div class="grid"><section class="card"><form data-form="ping"><div class="fields">${field('Reminder','<input name="title" required placeholder="Visit mom">',1)}${field('Date','<input name="date" type="date">')}${field('Time · optional','<input name="time" type="time">')}${field('Timing',`<select name="timing"><option value="specific">Specific / anytime</option><option value="before_bed">🌙 Before bed</option></select>`)}</div><div class="form-actions"><button class="btn primary">＋ New Little Ping</button></div></form></section><section class="card"><div class="card-head"><div><div class="ey">🔔 APPROVED REMINDERS</div><h2>Little Pings</h2></div><div class="count">${rows.filter(x=>!x.completed).length}</div></div><div class="stack">${rows.map(r=>`<div class="row grow ${r.completed?'done':''}"><button class="check" data-action="toggle-ping" data-id="${r.id}">${r.completed?'✓':'○'}</button><div><b>${esc(r.title)}</b><span class="meta">${r.date?fmtDate(r.date):'No fixed day'}${r.time?` · ${fmtTime(r.time)}`:''}${r.timing==='before_bed'?' · 🌙 Before bed':''}</span></div><button class="btn tiny" data-action="edit" data-kind="reminder" data-id="${r.id}">✏️</button>${archiveBtn('reminder',r.id)}<button class="btn tiny danger" data-action="delete" data-kind="reminder" data-id="${r.id}">×</button></div>`).join('')||'<div class="empty">No Pings. Your brain may roam freely.</div>'}</div></section></div></div>`}

function proposalHtml(){const p=state.mochini?.pendingProposal;if(!p)return'';if(p.kind==='clarify-task-reminder')return`<div class="proposal"><div class="ey">🤔 WHICH ROOM?</div><b>${esc(p.title)}</b><p>I understood the thing, just not what kind of thing you meant.</p><div class="button-row"><button class="btn primary" data-action="clarify" data-target="task">📝 Sweet To-Do</button><button class="btn" data-action="clarify" data-target="reminder">🔔 Little Ping</button><button class="btn" data-action="reject-proposal">Never mind</button></div></div>`;const label=p.kind==='task-batch'?`${p.payload.items.length} Sweet To-Dos`:p.kind==='reminder'?'Little Ping':'Sweet To-Do';return`<div class="proposal"><div class="ey">🔐 WAITING FOR KAT</div><b>${esc(label)} · ${esc(p.title)}</b><p>Mochini understood and staged it. Nothing has been created yet.</p><div class="button-row"><button class="btn primary" data-action="approve-proposal">♡ Approve</button><button class="btn" data-action="reject-proposal">Nope</button></div></div>`}
function mochiniView(){const turns=list(state.mochini?.conversation);return`<div class="page"><section class="hero"><div class="ey">🍡 MOCHINI BRAIN 2.0</div><h2>Talk like yourself. Organizing is her job.</h2><p>Obvious task → task. Obvious reminder → Ping. Multiple actions → split. Confusing context → ask. Conversation → stays conversation.</p></section><section class="card full"><div class="conversation" id="conversation">${turns.length?turns.map(t=>`<div class="turn ${t.role}"><b>${t.role==='assistant'?'🍡 MOCHINI':'KAT'}</b>${esc(t.text)}</div>`).join(''):'<div class="empty">Try “need to get vase,” “remind me to visit mom,” or “I have to clean the bathroom and put up dishes.”</div>'}</div>${proposalHtml()}<form data-form="mochini" class="chat-row"><input name="message" autocomplete="off" placeholder="Talk to Mochini normally…"><button class="btn primary">Send</button></form><div class="button-row" style="margin-top:8px"><button class="btn tiny" data-action="clear-chat">Clear chat only</button></div></section></div>`}

function routineInstance(template,date=today()){let found=list(state.life.routineInstances).find(x=>x.routineId===template.id&&x.date===date);if(!found){found={id:makeId('routine-instance'),routineId:template.id,date,status:'active',stepStates:Object.fromEntries(list(template.steps).map(s=>[s.id,false])),updatedAt:new Date().toISOString()};state.life.routineInstances.push(found)}return found}
function routineOccurs(r,date=today()){if(r.archived||archived('routine',r.id))return false;const d=new Date(`${date}T12:00:00`),day=d.getDay();if(r.recurrence==='manual')return !!list(state.life.routineInstances).find(x=>x.routineId===r.id&&x.date===date);if(r.recurrence==='weekdays')return day>=1&&day<=5;if(r.recurrence==='weekends')return day===0||day===6;if(r.recurrence==='selected')return list(r.days).map(Number).includes(day);return true}
function routineRow(r){const inst=routineInstance(r),steps=list(r.steps),done=steps.filter(s=>inst.stepStates?.[s.id]).length,skip=inst.status==='skipped',defer=inst.status==='deferred';return`<div class="cardlet"><div class="card-head"><div><div class="ey">${esc(r.icon||'🎀')} ${esc(r.daypart||'ANY TIME')}</div><h2 style="font-size:20px">${esc(r.name||r.title)}</h2><p>${skip?'Skipped today. Remaining steps are not counted as undone.':defer?'Deferred today. It can come back without pretending today failed.':inst.status==='completed'?'Finished ✨':`${done}/${steps.length} steps`}</p></div></div>${(!skip&&!defer&&inst.status!=='completed')?`<div class="stack">${steps.map(s=>`<div class="row grow"><button class="check" data-action="routine-step" data-routine="${r.id}" data-step="${s.id}">${inst.stepStates?.[s.id]?'✓':'○'}</button><div><b>${esc(s.label||s.text)}</b><span class="meta">${Number(s.minutes||5)}m${s.optional?' · optional':''}</span></div></div>`).join('')}</div>`:''}<div class="button-row" style="margin-top:10px">${inst.status==='active'?`<button class="btn tiny" data-action="routine-finish" data-id="${r.id}">✓ Finish</button><button class="btn tiny" data-action="routine-skip" data-id="${r.id}">Skip today</button><button class="btn tiny" data-action="routine-defer" data-id="${r.id}">Defer</button>`:`<button class="btn tiny" data-action="routine-reactivate" data-id="${r.id}">↩ Bring it back</button>`}${archiveBtn('routine',r.id)}</div></div>`}
function routinesView(){const rows=active('routine',state.life.routines).filter(r=>routineOccurs(r));return`<div class="page"><section class="hero"><div class="ey">🔁 ROUTINES</div><h2>Repeatable life, without streak court</h2><p>Partial counts. Skip means skip. Defer means defer. Tomorrow is allowed to be a normal day.</p></section><div class="grid"><section class="card full"><form data-form="routine"><div class="fields">${field('Routine name','<input name="name" required placeholder="Night routine">')}${field('Icon','<input name="icon" value="🎀">')}${field('Daypart',`<select name="daypart"><option>morning</option><option>daytime</option><option>evening</option><option>bedtime</option><option selected>any</option></select>`)}${field('Repeats',`<select name="recurrence"><option selected>daily</option><option>weekdays</option><option>weekends</option><option>manual</option></select>`)}${field('Steps · one per line','<textarea name="steps" placeholder="Brush teeth\nWash face\nBonnet"></textarea>',1)}</div><div class="form-actions"><button class="btn primary">＋ Add Routine</button></div></form></section><section class="card full"><div class="card-head"><div><div class="ey">TODAY</div><h2>${rows.length} routine${rows.length===1?'':'s'} in play</h2></div></div><div class="masonry">${rows.map(routineRow).join('')||'<div class="empty">No routine is scheduled today.</div>'}</div></section></div></div>`}

function nomsFoodRow(f){const tracked=f.trackQuantity===true||f.quantity!==undefined,qty=Math.max(0,Number(f.quantity)||0),low=tracked&&qty>0&&qty<=Math.max(0,Number(f.lowAt)||1),out=tracked&&qty<=0;return`<div class="row grow"><div>${out?'🧊':low?'⚠️':'🍓'}</div><div><b>${esc(f.name)}</b><span class="meta">${tracked?(out?'OUT · 0 left':`${qty} left${low?' · LOW':''}`):(f.available===false?'Unavailable':'Available')} · ${esc(f.kind||'Nom')}</span></div><div class="button-row"><button class="btn tiny" data-action="log-nom" data-id="${f.id}">🍽 Log</button>${archiveBtn('food',f.id)}</div></div>`}
function nomsView(){const tab=state.v4.ui.nomsTab||'fridge',n=obj(state.nourish.noms),foods=active('food',n.foods),recipes=active('recipe',n.recipes),groceries=list(n.groceries),history=list(n.history).filter(x=>x.date===today()).slice().reverse(),tracked=foods.filter(f=>f.trackQuantity===true||f.quantity!==undefined);const tabs=[['fridge','🧊 Mini Fridge'],['saved','🍓 Saved Noms'],['grocery','🛒 Grocery Basket'],['meal','📅 Meal Plan'],['recipes','📖 Recipes'],['diary','🍽 Diary']];let body='';if(tab==='fridge')body=`<div class="stack">${tracked.map(f=>`<div class="row grow"><div>🧊</div><div><b>${esc(f.name)}</b><span class="meta">${Math.max(0,Number(f.quantity)||0)} left · low at ${Math.max(0,Number(f.lowAt)||1)}</span></div><input style="width:70px" data-stock-qty="${f.id}" type="number" min="0" value="${Math.max(0,Number(f.quantity)||0)}"><input style="width:70px" data-stock-low="${f.id}" type="number" min="0" value="${Math.max(0,Number(f.lowAt)||1)}"><button class="btn tiny" data-action="save-stock" data-id="${f.id}">Save stock</button>${archiveBtn('food',f.id)}</div>`).join('')||'<div class="empty">No quantity-tracked Noms yet.</div>'}</div><form data-form="food" style="margin-top:12px"><div class="fields">${field('Quick-add stocked Nom','<input name="name" required placeholder="Canned pineapple">')}${field('Qty','<input name="quantity" type="number" min="0" value="1">')}${field('Low at','<input name="lowAt" type="number" min="0" value="1">')}</div><div class="form-actions"><button class="btn primary">＋ Add Nom</button></div></form>`;else if(tab==='saved')body=`<div class="stack">${foods.map(nomsFoodRow).join('')||'<div class="empty">No saved Noms yet.</div>'}</div>`;else if(tab==='grocery')body=`<form data-form="grocery"><div class="fields">${field('What do we need?','<input name="name" required placeholder="Cat food">')}${field('Quantity','<input name="quantity" placeholder="1 bag">')}</div><div class="form-actions"><button class="btn primary">＋ Add to basket</button></div></form><div class="stack" style="margin-top:12px">${groceries.map(g=>`<div class="row grow ${g.checked?'done':''}"><button class="check" data-action="grocery-toggle" data-id="${g.id}">${g.checked?'✓':'○'}</button><div><b>${esc(g.name||g.title)}</b><span class="meta">${esc(g.quantity||'')}</span></div><button class="btn tiny danger" data-action="delete" data-kind="grocery" data-id="${g.id}">×</button></div>`).join('')||'<div class="empty">Basket empty.</div>'}</div>`;else if(tab==='meal')body=`<form data-form="meal"><div class="fields">${field('Plan a Nom','<input name="label" required placeholder="Dinner with Jordan, leftovers, etc.">')}${field('Date',`<input name="date" type="date" value="${today()}">`)}${field('Slot',`<select name="slot"><option>breakfast</option><option>lunch</option><option>dinner</option><option>snack</option><option selected>any</option></select>`)}</div><div class="form-actions"><button class="btn primary">＋ Plan Nom</button></div></form><div class="stack" style="margin-top:12px">${list(n.mealPlan).map(x=>`<div class="row grow"><div>📅</div><div><b>${esc(x.label||x.name)}</b><span class="meta">${fmtDate(x.date)} · ${esc(x.slot)}</span></div></div>`).join('')||'<div class="empty">Nothing planned. Spontaneous eating remains legal. 😂</div>'}</div>`;else if(tab==='recipes')body=`<form data-form="recipe"><div class="fields">${field('Recipe','<input name="name" required>')}${field('Prep minutes','<input name="prepMinutes" type="number" value="15">')}${field('Ingredients','<textarea name="ingredients" placeholder="comma separated"></textarea>',1)}</div><div class="form-actions"><button class="btn primary">＋ Save recipe</button></div></form><div class="stack" style="margin-top:12px">${recipes.map(r=>`<div class="row grow"><div>📖</div><div><b>${esc(r.name)}</b><span class="meta">${Number(r.prepMinutes||15)}m · ${list(r.ingredients).join(', ')}</span></div>${archiveBtn('recipe',r.id)}</div>`).join('')||'<div class="empty">No recipes yet.</div>'}</div>`;else body=`<form data-form="nom-log"><div class="fields">${field('What did you have?','<input name="name" required>')}</div><div class="form-actions"><button class="btn primary">＋ Log manual Nom</button></div></form><div class="stack" style="margin-top:12px">${history.map(x=>`<div class="row grow"><div>🍽</div><div><b>${esc(x.name)}</b><span class="meta">${fmtDate(x.date)} · ${x.loggedAt?new Date(x.loggedAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}):''}</span></div><button class="btn tiny danger" data-action="delete" data-kind="nom-log" data-id="${x.id}">×</button></div>`).join('')||'<div class="empty">Nothing logged today yet.</div>'}</div>`;return`<div class="page"><section class="hero"><div class="ey">🍱 NOMS NOOK</div><h2>Feed me immediately, but make it organized</h2><p>One food record powers Saved Noms, Mini Fridge stock, logging, diary, and grocery suggestions. No kitchen multiverse.</p></section><section class="card full"><div class="tabs">${tabs.map(([id,label])=>`<button class="tab ${tab===id?'active':''}" data-noms-tab="${id}">${label}</button>`).join('')}</div>${body}</section></div>`}

function sipsView(){const s=obj(state.nourish.sips),goal=Math.max(8,Number(s.waterGoalOz)||64),entries=list(s.history).filter(x=>x.date===today()),water=entries.filter(x=>x.type==='water').reduce((a,b)=>a+Number(b.ounces||0),0),total=entries.reduce((a,b)=>a+Number(b.ounces||0),0),pct=Math.min(100,Math.round(water/goal*100));return`<div class="page"><section class="hero"><div class="ey">💧 SIP STATION</div><h2>${water>=goal?'Goal met. Hydrated icon behavior.':'Water is the goal; everything still gets logged.'}</h2><p>Local calendar date is authoritative, so yesterday’s drinks stay yesterday’s problem.</p></section><div class="grid"><section class="card"><div class="ey">💧 WATER GOAL</div><div class="big-number">${water} / ${goal} oz</div><div class="progress"><i style="width:${pct}%"></i></div><p style="margin-top:8px">${pct}% · Other drinks live in the diary but do not move this bar.</p></section><section class="card"><div class="ey">🥤 TOTAL DRINKS TODAY</div><div class="big-number">${total} oz</div><p>${entries.length} drink${entries.length===1?'':'s'} · ${water} oz water + ${Math.max(0,total-water)} oz other</p></section><section class="card full"><form data-form="sip"><div class="fields">${field('Drink name','<input name="name" placeholder="Water, Sprite, Gatorade">')}${field('Ounces','<input name="ounces" type="number" min="1" required value="8">')}${field('Drink type',`<select name="type"><option value="water">💧 Water</option><option value="soda">🥤 Soda</option><option value="juice">🧃 Juice</option><option value="coffee-tea">☕ Coffee / Tea</option><option value="sports">⚡ Sports / Electrolyte</option><option value="other">✨ Other</option></select>`)}${field('Daily water goal','<input name="goal" type="number" min="8" value="'+goal+'">')}</div><div class="form-actions"><button class="btn primary">＋ Log Sip</button></div></form><div class="stack" style="margin-top:12px">${entries.slice().reverse().map(x=>`<div class="row grow"><div>${x.type==='water'?'💧':x.type==='soda'?'🥤':x.type==='sports'?'⚡':'🥤'}</div><div><b>${esc(x.name)} · ${Number(x.ounces)} oz</b><span class="meta">${esc(x.type)} · ${new Date(x.loggedAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</span></div><button class="btn tiny danger" data-action="delete" data-kind="sip" data-id="${x.id}">×</button></div>`).join('')||'<div class="empty">Fresh day. Zero drinks logged.</div>'}</div></section></div></div>`}

function motionView(){const sessions=active('motion-session',state.movement.sessions).slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))),recipes=active('motion-recipe',state.movement.routines),todaySessions=sessions.filter(x=>x.date===today()),minutes=todaySessions.reduce((a,b)=>a+Number(b.minutes||0),0);return`<div class="page"><section class="hero"><div class="ey">🌿 MOTION MEADOW</div><h2>Look at me moving ✨</h2><p>Log today or backfill a past session. History belongs to the day it actually happened.</p></section><div class="grid"><section class="card"><div class="ey">TODAY</div><div class="big-number">${minutes} minutes</div><p>${todaySessions.length} session${todaySessions.length===1?'':'s'} today.</p></section><section class="card"><form data-form="motion"><div class="fields">${field('Movement',`<select name="type"><option>walk</option><option>treadmill</option><option selected>pilates</option><option>stretch</option><option>strength</option><option>other</option></select>`)}${field('Minutes','<input name="minutes" type="number" min="1" value="15">')}${field('Date it happened',`<input name="date" type="date" value="${today()}">`)}${field('Effort',`<select name="effort"><option>low</option><option selected>medium</option><option>high</option></select>`)}</div><div class="form-actions"><button class="btn primary">＋ Log movement</button></div></form></section><section class="card full"><div class="ey">🌷 SAVED MOVEMENT</div><div class="stack">${recipes.map(r=>`<div class="row grow"><div>🌷</div><div><b>${esc(r.name)}</b><span class="meta">${Number(r.minutes||10)}m · ${esc(r.type||'movement')} · ${esc(r.effort||'medium')}</span></div><button class="btn tiny" data-action="motion-recipe-log" data-id="${r.id}">Log</button>${archiveBtn('motion-recipe',r.id)}</div>`).join('')||'<div class="empty">No saved movement recipes yet.</div>'}</div></section><section class="card full"><div class="ey">🗓 RECENT MOVEMENT</div><div class="stack">${sessions.slice(0,20).map(s=>`<div class="row grow"><div>🌿</div><div><b>${esc(s.label||s.name||s.type)}</b><span class="meta">${fmtDate(s.date)} · ${Number(s.minutes||0)}m · ${esc(s.effort||'')}</span></div><button class="btn tiny danger" data-action="delete" data-kind="motion-session" data-id="${s.id}">×</button></div>`).join('')||'<div class="empty">No movement logged yet.</div>'}</div></section></div></div>`}

function peopleView(){const rows=active('person',state.v4.people);return`<div class="page"><section class="hero"><div class="ey">💕 PEOPLE & PLANS</div><h2>People I actually care about, not a corporate CRM</h2><p>Useful context for plans, dates, gifts, and Mochini suggestions. Deleted connections are dead to KatOS.</p></section><div class="grid"><section class="card"><form data-form="person"><div class="fields">${field('Name','<input name="name" required>')}${field('Relationship / context','<input name="relationship" placeholder="friend, boyfriendn’t, sister…">')}${field('Things we like doing','<textarea name="likes"></textarea>',1)}${field('Important dates','<input name="importantDates">')}${field('Gift ideas','<textarea name="giftIdeas"></textarea>',1)}</div><div class="form-actions"><button class="btn primary">＋ Add person</button></div></form></section><section class="card"><div class="stack">${rows.map(p=>`<div class="row grow"><div>💕</div><div><b>${esc(p.name)}</b><span class="meta">${esc(p.relationship||'person')} ${p.likes?`· ${esc(p.likes)}`:''}</span></div><button class="btn tiny" data-action="edit" data-kind="person" data-id="${p.id}">✏️</button>${archiveBtn('person',p.id)}<button class="btn tiny danger" data-action="delete" data-kind="person" data-id="${p.id}">×</button></div>`).join('')||'<div class="empty">No people cards yet.</div>'}</div></section></div></div>`}
function hobbiesView(){const rows=active('hobby',state.v4.hobbies);return`<div class="page"><section class="hero"><div class="ey">🎨 HOBBY SHELF</div><h2>Things I like before I forget I like them</h2><p>Playing, on the shelf, curious about, and language lanes all live here without streak shame.</p></section><div class="grid"><section class="card"><form data-form="hobby"><div class="fields">${field('Hobby','<input name="name" required>')}${field('Status',`<select name="status"><option value="playing">✨ Playing</option><option value="shelf">📚 On the shelf</option><option value="curious">👀 Curious about</option></select>`)}${field('Kind / language','<input name="kind" placeholder="Chinese, Funko, cosplay…">')}${field('Language lane?',`<select name="language"><option value="false">No</option><option value="true">🌎 Yes</option></select>`)}${field('Notes','<textarea name="notes"></textarea>',1)}</div><div class="form-actions"><button class="btn primary">＋ Add hobby</button></div></form></section><section class="card"><div class="stack">${rows.map(h=>`<div class="row grow"><div>${h.language?'🌎':h.status==='playing'?'✨':h.status==='shelf'?'📚':'👀'}</div><div><b>${esc(h.name)}</b><span class="meta">${esc(h.status)}${h.lastTouched?` · last touched ${fmtDate(h.lastTouched)}`:''}</span></div><button class="btn tiny" data-action="touch-hobby" data-id="${h.id}">I did this</button>${archiveBtn('hobby',h.id)}</div>`).join('')||'<div class="empty">Your hobby shelf is waiting for the chaos.</div>'}</div></section></div></div>`}

function bossView(){const w=obj(state.work),items=active('work-item',w.items),shifts=active('shift',w.shifts),training=active('training',w.training),career=active('career',w.career),focus=obj(w.focus);return`<div class="page"><section class="hero"><div class="ey">💼 BOSS BITCH</div><h2>Work brain lives here so Home doesn’t become LinkedIn</h2><p>Shifts, work queue, training, focus sprints, and career stuff stay connected to Berry Busy and Money Café.</p></section><div class="grid"><section class="card"><div class="ey">⚡ FOCUS SPRINT</div><h2>${focus.active?esc(focus.label||'Locked in'):'Clock in mentally'}</h2><p>${focus.active?`Started ${new Date(focus.startedAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})} · planned ${Number(focus.minutes||0)}m`:'Start one focused work block without pretending you signed a blood oath.'}</p><div class="button-row" style="margin-top:10px">${focus.active?'<button class="btn dark" data-action="focus-stop">Stop sprint</button>':'<button class="btn primary" data-action="focus-start">Start 25m sprint</button>'}</div></section><section class="card"><form data-form="work-item"><div class="fields">${field('Work item','<input name="text" required>')}${field('Due','<input name="dueDate" type="date">')}${field('Minutes','<input name="minutes" type="number" value="15">')}${field('Protected?',`<select name="protected"><option value="false">Flexible</option><option value="true">Protected</option></select>`)}</div><div class="form-actions"><button class="btn primary">＋ Add work item</button></div></form></section><section class="card full"><div class="ey">📋 WORK QUEUE</div><div class="stack">${items.map(x=>`<div class="row grow ${x.done?'done':''}"><button class="check" data-action="toggle-work" data-id="${x.id}">${x.done?'✓':'○'}</button><div><b>${esc(x.text||x.title)}</b><span class="meta">${x.dueDate?fmtDate(x.dueDate):'No due date'} · ${Number(x.minutes||15)}m${x.protected?' · 🔒':''}</span></div>${archiveBtn('work-item',x.id)}</div>`).join('')||'<div class="empty">Work queue empty.</div>'}</div></section><section class="card"><div class="ey">🗓 SHIFTS</div><form data-form="shift"><div class="fields">${field('Label','<input name="label" value="Work shift">')}${field('Date',`<input name="date" type="date" value="${today()}">`)}${field('Start','<input name="startTime" type="time">')}${field('End','<input name="endTime" type="time">')}</div><div class="form-actions"><button class="btn">＋ Add shift</button></div></form><div class="stack" style="margin-top:10px">${shifts.slice().sort((a,b)=>String(a.date).localeCompare(String(b.date))).slice(0,8).map(s=>`<div class="row grow"><div>💼</div><div><b>${esc(s.label)}</b><span class="meta">${fmtDate(s.date)} · ${fmtTime(s.startTime)}–${fmtTime(s.endTime)}</span></div>${archiveBtn('shift',s.id)}</div>`).join('')}</div></section><section class="card"><div class="ey">🪜 TRAINING + CAREER</div><div class="stack">${training.map(t=>`<div class="row grow"><div>🪜</div><div><b>${esc(t.title)}</b><span class="meta">${Number(t.progress||0)}%${t.dueDate?` · ${fmtDate(t.dueDate)}`:''}</span></div>${archiveBtn('training',t.id)}</div>`).join('')}${career.map(c=>`<div class="row grow"><div>✨</div><div><b>${esc(c.title)}</b><span class="meta">${esc(c.note||'career thing')}</span></div>${archiveBtn('career',c.id)}</div>`).join('')||'<div class="empty">No training/career records yet.</div>'}</div></section></div></div>`}

const debtTypes=[['credit-card','Credit Card 💳'],['car-loan','Car Loan 🚗'],['personal-loan','Personal Loan 💸'],['student-loan','Student Loan 🎓'],['mortgage','Mortgage 🏠'],['medical','Medical Debt 🩹'],['bnpl','Buy Now, Cry Later 😭'],['line-of-credit','Line of Credit'],['other','Other unfortunate circumstances']];
function moneySnapshot(){const m=obj(state.money),cash=list(m.accounts).reduce((a,b)=>a+Number(b.balance||0),0),bills=active('bill',m.bills).filter(x=>!x.paid),due=bills.reduce((a,b)=>a+Number(b.amount||0),0),debt=active('debt',m.debts).reduce((a,b)=>a+Number(b.balance||0),0),savings=list(m.savingsGoals).reduce((a,b)=>a+Number(b.current||0),0);return{cash,due,debt,savings,left:cash-due}}
function moneyView(){const tab=state.v4.ui.moneyTab||'overview',m=obj(state.money),snap=moneySnapshot(),tabs=[['overview','✨ Overview'],['income','💸 Moneyyy'],['bills','🧾 Shit I Don’t Wanna Pay'],['debt','💀 Dumb Debt'],['savings','💗 Future Kat'],['spending','🛍 Where Tf Did It Go?'],['want','🎀 Things I Want']];let body='';if(tab==='overview')body=`<div class="summary-grid"><div class="mini-stat"><small>MONEY I CAN SEE</small><b>${currency(snap.cash)}</b></div><div class="mini-stat"><small>SHIT I DON'T WANNA PAY</small><b>${currency(snap.due)}</b></div><div class="mini-stat"><small>DUMB DEBT</small><b>${currency(snap.debt)}</b></div><div class="mini-stat"><small>CAN I AFFORD TO BE SILLY?</small><b>${currency(snap.left)}</b></div></div><div class="callout" style="margin-top:12px"><b>One source of truth:</b> debt payment details create/update the linked bill automatically. No double-entry financial demons.</div>`;else if(tab==='income')body=`<form data-form="earning"><div class="fields">${field('Description','<input name="label" required placeholder="Paycheck">')}${field('Amount','<input name="amount" type="number" step=".01" required>')}${field('Expected / received date',`<input name="date" type="date" value="${today()}">`)}${field('Status',`<select name="status"><option>expected</option><option>received</option></select>`)}</div><div class="form-actions"><button class="btn primary">＋ Add money</button></div></form><div class="stack" style="margin-top:12px">${list(m.earnings).map(e=>`<div class="row grow"><div>💸</div><div><b>${esc(e.label||'Income')}</b><span class="meta">${currency(e.receivedAmount||e.actualGross||e.estimatedGross||e.grossEarned||0)} · ${esc(e.status||'')}</span></div></div>`).join('')||'<div class="empty">No income records yet.</div>'}</div>`;else if(tab==='bills')body=`<form data-form="bill"><div class="fields">${field('Bill','<input name="name" required>')}${field('Amount','<input name="amount" type="number" step=".01" required>')}${field('Due date · optional','<input name="dueDate" type="date">')}${field('Due day each month','<input name="dueDay" type="number" min="1" max="31">')}</div><div class="form-actions"><button class="btn primary">＋ Add bill</button></div></form><div class="stack" style="margin-top:12px">${active('bill',m.bills).map(b=>`<div class="row grow ${b.paid?'done':''}"><button class="check" data-action="bill-paid" data-id="${b.id}">${b.paid?'✓':'○'}</button><div><b>${esc(b.name)}</b><span class="meta">${currency(b.amount)} · ${b.dueDate?fmtDate(b.dueDate):b.dueDay?`due day ${b.dueDay}`:'no due date'}${b.linkedDebtId?' · 🔗 linked to debt':''}</span></div>${archiveBtn('bill',b.id)}</div>`).join('')||'<div class="empty">No bills yet.</div>'}</div>`;else if(tab==='debt')body=`<form data-form="debt"><div class="fields">${field('What kind of financial burden is this?',`<select name="type">${debtTypes.map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select>`)}${field('Name','<input name="name" required placeholder="Navy Federal / Honda Civic">')}${field('Balance','<input name="balance" type="number" step=".01">')}${field('APR %','<input name="apr" type="number" step=".01">')}${field('Minimum / monthly payment','<input name="paymentAmount" type="number" step=".01">')}${field('Due day','<input name="dueDay" type="number" min="1" max="31">')}${field('Credit limit · cards only','<input name="creditLimit" type="number" step=".01">')}${field('Lender / issuer','<input name="lender">')}</div><div class="form-actions"><button class="btn primary">＋ Add debt + linked bill</button></div></form><div class="stack" style="margin-top:12px">${active('debt',m.debts).map(d=>`<div class="row grow"><div>💀</div><div><b>${esc(d.name)}</b><span class="meta">${esc(debtTypes.find(x=>x[0]===d.type)?.[1]||d.type)} · ${currency(d.balance)} · payment ${currency(d.paymentAmount||d.minimum)}${d.dueDay?` · due ${d.dueDay}`:''}${d.creditLimit?` · ${(d.balance/d.creditLimit*100).toFixed(0)}% utilization`:''} · 🔗 bill linked</span></div><button class="btn tiny" data-action="edit" data-kind="debt" data-id="${d.id}">✏️</button>${archiveBtn('debt',d.id)}<button class="btn tiny danger" data-action="delete" data-kind="debt" data-id="${d.id}">×</button></div>`).join('')||'<div class="empty">No dumb debt. Love that for you.</div>'}</div>`;else if(tab==='savings')body=`<form data-form="savings"><div class="fields">${field('Goal','<input name="name" required placeholder="Emergency fund">')}${field('Current','<input name="current" type="number" step=".01">')}${field('Target','<input name="target" type="number" step=".01">')}</div><div class="form-actions"><button class="btn primary">＋ Future Kat fund</button></div></form><div class="stack" style="margin-top:12px">${list(m.savingsGoals).map(g=>`<div class="row grow"><div>💗</div><div><b>${esc(g.name)}</b><span class="meta">${currency(g.current)} / ${currency(g.target)}</span><div class="progress"><i style="width:${g.target?Math.min(100,g.current/g.target*100):0}%"></i></div></div></div>`).join('')||'<div class="empty">No savings goals yet.</div>'}</div>`;else if(tab==='spending')body=`<form data-form="spending"><div class="fields">${field('What did Future Me buy?','<input name="description" required>')}${field('Amount','<input name="amount" type="number" step=".01" required>')}${field('Category','<input name="category" placeholder="food, fun, bills…">')}${field('Date',`<input name="date" type="date" value="${today()}">`)}</div><div class="form-actions"><button class="btn primary">＋ Log spending</button></div></form><div class="stack" style="margin-top:12px">${list(m.spending).slice().reverse().slice(0,30).map(x=>`<div class="row grow"><div>🛍</div><div><b>${esc(x.description)}</b><span class="meta">${currency(x.amount)} · ${esc(x.category||'other')} · ${fmtDate(x.date)}</span></div></div>`).join('')||'<div class="empty">No spending records yet.</div>'}</div>`;else body=`<form data-form="wish"><div class="fields">${field('Thing I want for reasons','<input name="name" required>')}${field('Price','<input name="price" type="number" step=".01">')}${field('Category','<input name="category">')}${field('Why do I want it?','<input name="why">')}${field('Wait until · optional','<input name="waitUntil" type="date">')}</div><div class="form-actions"><button class="btn primary">＋ Add to wishlist</button></div></form><div class="stack" style="margin-top:12px">${active('wish',state.v4.shopping).map(w=>`<div class="row grow"><div>🎀</div><div><b>${esc(w.name)}</b><span class="meta">${currency(w.price)} · ${esc(w.category)}${w.waitUntil?` · wait until ${fmtDate(w.waitUntil)}`:''}</span></div>${archiveBtn('wish',w.id)}</div>`).join('')||'<div class="empty">Nothing on the wishlist.</div>'}</div>`;return`<div class="page"><section class="hero"><div class="ey">☕ MONEY CAFÉ</div><h2>I would like to be rich now please</h2><p>Money is serious data wearing funny labels. Cute outside, precise underneath.</p></section><section class="card full"><div class="tabs">${tabs.map(([id,l])=>`<button class="tab ${tab===id?'active':''}" data-money-tab="${id}">${l}</button>`).join('')}</div>${body}</section></div>`}

function studyView(){const e=obj(state.education),courses=active('course',e.courses),items=active('study-item',e.items),sessions=list(e.sessions);return`<div class="page"><section class="hero"><div class="ey">🎓 STUDY NOOK</div><h2>Self-paced does not mean floating in the void</h2><p>Courses keep objectives, milestones, program deadlines, work items, sessions, and reflections together.</p></section><div class="grid"><section class="card"><form data-form="course"><div class="fields">${field('Course','<input name="title" required>')}${field('Progress %','<input name="progress" type="number" min="0" max="100" value="0">')}${field('Current objective','<input name="currentObjective">')}${field('Next milestone','<input name="nextMilestone">')}${field('Target date','<input name="targetDate" type="date">')}</div><div class="form-actions"><button class="btn primary">＋ Add course</button></div></form></section><section class="card"><form data-form="study-item"><div class="fields">${field('Study item','<input name="title" required>')}${field('Course',`<select name="courseId"><option value="">No course</option>${courses.map(c=>`<option value="${c.id}">${esc(c.title||c.name)}</option>`).join('')}</select>`)}${field('Due','<input name="dueDate" type="date">')}${field('Minutes','<input name="minutes" type="number" value="15">')}</div><div class="form-actions"><button class="btn primary">＋ Add study item</button></div></form></section><section class="card full"><div class="ey">📚 COURSES</div><div class="stack">${courses.map(c=>`<div class="row grow"><div>🎓</div><div><b>${esc(c.title||c.name)}</b><span class="meta">${Number(c.progress||0)}% · ${esc(c.currentObjective||'No current objective')}${c.nextMilestone?` · next: ${esc(c.nextMilestone)}`:''}</span><div class="progress"><i style="width:${Math.max(0,Math.min(100,Number(c.progress)||0))}%"></i></div></div>${archiveBtn('course',c.id)}</div>`).join('')||'<div class="empty">No courses yet.</div>'}</div></section><section class="card"><div class="ey">📝 STUDY QUEUE</div><div class="stack">${items.map(i=>`<div class="row grow ${i.done?'done':''}"><button class="check" data-action="toggle-study" data-id="${i.id}">${i.done?'✓':'○'}</button><div><b>${esc(i.title)}</b><span class="meta">${i.dueDate?fmtDate(i.dueDate):'No due date'} · ${Number(i.minutes||15)}m</span></div>${archiveBtn('study-item',i.id)}</div>`).join('')||'<div class="empty">No study queue.</div>'}</div></section><section class="card"><div class="ey">⏱ LOG STUDY</div><form data-form="study-session"><div class="fields">${field('Course',`<select name="courseId">${courses.map(c=>`<option value="${c.id}">${esc(c.title||c.name)}</option>`).join('')}</select>`)}${field('Minutes','<input name="minutes" type="number" value="30">')}${field('Date',`<input name="date" type="date" value="${today()}">`)}</div><div class="form-actions"><button class="btn">＋ Log session</button></div></form><p style="margin-top:10px">${sessions.filter(s=>s.date===today()).reduce((a,b)=>a+Number(b.minutes||0),0)} minutes logged today.</p></section></div></div>`}

function threadsView(){const rows=active('thread',state.life.threads).filter(t=>t.status!=='archived'&&t.status!=='complete');return`<div class="page"><section class="hero"><div class="ey">🧵 THREADS</div><h2>Projects leave the task list when they become a whole situation</h2><p>Active and paused projects stay on the desk. Finished/archived ones go to Memory Box.</p></section><div class="grid"><section class="card"><form data-form="thread"><div class="fields">${field('Project / Thread','<input name="title" required>')}${field('Status',`<select name="status"><option>active</option><option>paused</option></select>`)}${field('Target date','<input name="deadline" type="date">')}${field('What is this?','<textarea name="summary"></textarea>',1)}</div><div class="form-actions"><button class="btn primary">＋ Start Thread</button></div></form></section><section class="card"><div class="stack">${rows.map(t=>`<div class="row grow"><div>${esc(t.icon||'🧵')}</div><div><b>${esc(t.title)}</b><span class="meta">${esc(t.status)}${t.deadline?` · ${fmtDate(t.deadline)}`:''}${t.summary?` · ${esc(t.summary)}`:''}</span></div><button class="btn tiny" data-action="thread-status" data-id="${t.id}" data-status="${t.status==='paused'?'active':'paused'}">${t.status==='paused'?'Resume':'Pause'}</button>${archiveBtn('thread',t.id)}</div>`).join('')||'<div class="empty">No active projects. The desk is clean.</div>'}</div></section></div></div>`}

function growthView(){const g=obj(state.growth),goals=active('goal',g.goals),wins=active('win',g.wins),experiments=active('experiment',g.experiments);return`<div class="page"><section class="hero"><div class="ey">🌱 GROWTH ROOM</div><h2>Progress without turning my life into percentages</h2><p>Goals, wins, and true experiments belong here. Routines are not experiments just because migration got creative once.</p></section><div class="grid"><section class="card"><form data-form="goal"><div class="fields">${field('Goal','<input name="title" required>')}${field('Why','<input name="why">')}${field('Target date','<input name="targetDate" type="date">')}</div><div class="form-actions"><button class="btn primary">＋ Add goal</button></div></form><div class="stack" style="margin-top:12px">${goals.map(g=>`<div class="row grow"><div>🌱</div><div><b>${esc(g.title)}</b><span class="meta">${esc(g.status||'moving')}${g.targetDate?` · ${fmtDate(g.targetDate)}`:''}</span></div>${archiveBtn('goal',g.id)}</div>`).join('')}</div></section><section class="card"><form data-form="win"><div class="fields">${field('Win','<input name="title" required placeholder="Started the thing">')}${field('Note','<input name="note">')}</div><div class="form-actions"><button class="btn">✨ Save win</button></div></form><div class="stack" style="margin-top:12px">${wins.slice().reverse().slice(0,10).map(w=>`<div class="row grow"><div>✨</div><div><b>${esc(w.title)}</b><span class="meta">${fmtDate(w.date||String(w.createdAt).slice(0,10))}</span></div>${archiveBtn('win',w.id)}</div>`).join('')}</div></section><section class="card full"><div class="ey">🔬 TRUE EXPERIMENTS</div><div class="stack">${experiments.map(e=>`<div class="row grow"><div>🔬</div><div><b>${esc(e.title)}</b><span class="meta">${esc(e.hypothesis||e.behavior||'Try it and see')} · ${list(e.attempts).length} attempts</span></div>${archiveBtn('experiment',e.id)}</div>`).join('')||'<div class="empty">No experiments running.</div>'}</div></section></div></div>`}

function dumpView(){const rows=active('dump',state.v4.brainDump),closed=rows.filter(x=>x.bucket==='closed'),open=rows.filter(x=>x.bucket!=='closed');return`<div class="page"><section class="hero"><div class="ey">🧠 GET IT OUTTA MY HEAD</div><h2>Dump first. Categorize later.</h2><p>KatOS can hold hobby ideas, language ideas, KatOS ideas, and random thoughts without making you decide their destiny first.</p></section><div class="grid"><section class="card"><form data-form="dump"><div class="fields">${field('Brain dump','<textarea name="text" required></textarea>',1)}${field('Pile',`<select name="bucket"><option value="inbox">Unsorted pile</option><option value="idea">Idea attic</option><option value="hobby">Hobby idea</option><option value="language">Language idea</option><option value="katos">KatOS idea</option><option value="closed">🔒 Closed Drawer</option></select>`)}</div><div class="form-actions"><button class="btn primary">Get it outta my head</button></div></form></section><section class="card"><div class="stack">${open.slice().reverse().map(x=>`<div class="row grow"><div>💭</div><div><b>${esc(x.text)}</b><span class="meta">${esc(x.bucket)} · ${new Date(x.createdAt).toLocaleDateString()}</span></div>${archiveBtn('dump',x.id)}</div>`).join('')||'<div class="empty">Brain dump pile empty.</div>'}</div></section><section class="card full closed-drawer"><div class="ey" style="color:#f0a7c3">🔒 CLOSED DRAWER</div><h2 style="color:#fff">Negative rants stay asleep unless you deliberately open this.</h2><details><summary style="cursor:pointer;font-weight:800">Open drawer (${closed.length})</summary><div class="stack" style="margin-top:10px">${closed.map(x=>`<div class="row grow" style="color:#30262a"><div>🔒</div><div><b>${esc(x.text)}</b><span class="meta">${new Date(x.createdAt).toLocaleString()}</span></div></div>`).join('')||'<div class="empty">Nothing in here.</div>'}</div></details></section></div></div>`}

function adminView(){const rows=active('admin',state.v4.admin);return`<div class="page"><section class="hero"><div class="ey">🗃️ UNFORTUNATELY, I’M AN ADULT</div><h2>Important shit I can’t lose</h2><p>Documents, renewals, where the physical copy is hiding, and what the thing is even for.</p></section><div class="grid"><section class="card"><form data-form="admin"><div class="fields">${field('What is it?','<input name="name" required>')}${field('Type','<input name="kind" placeholder="document, renewal, account…">')}${field('Where is the physical copy?','<input name="physicalLocation">')}${field('Digital file / link','<input name="digitalLocation">')}${field('Expires / renews','<input name="expires" type="date">')}${field('Notes','<textarea name="notes"></textarea>',1)}</div><div class="form-actions"><button class="btn primary">＋ File important shit</button></div></form></section><section class="card"><div class="stack">${rows.map(x=>`<div class="row grow"><div>🗃️</div><div><b>${esc(x.name)}</b><span class="meta">${esc(x.kind)}${x.physicalLocation?` · 📍 ${esc(x.physicalLocation)}`:''}${x.expires?` · renew ${fmtDate(x.expires)}`:''}</span></div>${archiveBtn('admin',x.id)}</div>`).join('')||'<div class="empty">No life-admin records yet.</div>'}</div></section></div></div>`}

function reviewSnapshot(date=today()){const tasks=list(state.life.tasks).filter(x=>x.date===date||String(x.completedAt||'').startsWith(date)),routines=list(state.life.routines).filter(r=>routineOccurs(r,date)),inst=list(state.life.routineInstances).filter(x=>x.date===date),motion=list(state.movement.sessions).filter(x=>x.date===date),noms=list(state.nourish.noms.history).filter(x=>x.date===date),sips=list(state.nourish.sips.history).filter(x=>x.date===date),study=list(state.education.sessions).filter(x=>x.date===date),work=list(state.work.shifts).filter(x=>x.date===date),events=list(state.life.events).filter(x=>x.date===date);return{tasksDone:tasks.filter(doneLike).length,tasksOpen:tasks.filter(x=>!doneLike(x)).length,routinesDone:inst.filter(x=>x.status==='completed').length,routinesSkip:inst.filter(x=>x.status==='skipped').length,motionMinutes:motion.reduce((a,b)=>a+Number(b.minutes||0),0),noms:noms.length,sips:sips.length,studyMinutes:study.reduce((a,b)=>a+Number(b.minutes||0),0),workMinutes:work.reduce((a,s)=>{if(!s.startTime||!s.endTime)return a;const [x,y]=[s.startTime,s.endTime].map(t=>{const[h,m]=t.split(':').map(Number);return h*60+(m||0)});return a+Math.max(0,y-x)},0),events:events.length}}
function reviewView(){const date=today(),snap=reviewSnapshot(date),r=list(state.insights.dayReviews).find(x=>x.date===date)||{};return`<div class="page"><section class="hero"><div class="ey">🌙 DAY IN REVIEW</div><h2>So… how’d we do?</h2><p>KatOS already has the receipts. Your part can be three sentences, not a nightly autobiography.</p></section><section class="card full"><div class="summary-grid"><div class="mini-stat"><small>TASKS</small><b>${snap.tasksDone} done</b><span>${snap.tasksOpen} open</span></div><div class="mini-stat"><small>ROUTINES</small><b>${snap.routinesDone} finished</b><span>${snap.routinesSkip} skipped</span></div><div class="mini-stat"><small>MOVEMENT</small><b>${snap.motionMinutes}m</b></div><div class="mini-stat"><small>NOMS / SIPS</small><b>${snap.noms} / ${snap.sips}</b></div></div></section><section class="card full"><form data-form="review"><div class="fields">${field('Mood',`<select name="mood"><option value="">No rating</option>${['rough','meh','okay','good','great'].map(x=>`<option ${r.mood===x?'selected':''}>${x}</option>`).join('')}</select>`)}${field('Energy',`<select name="energy"><option value="">No rating</option>${['drained','low','okay','good','high'].map(x=>`<option ${r.energy===x?'selected':''}>${x}</option>`).join('')}</select>`)}${field('What happened?','<textarea name="happened" placeholder="Useful version, not a court transcript.">'+esc(r.happened||'')+'</textarea>',1)}${field('Proud of','<textarea name="proud">'+esc(r.proud||'')+'</textarea>',1)}${field('Tomorrow-Kat should know…','<textarea name="tomorrow">'+esc(r.tomorrow||'')+'</textarea>',1)}</div><details style="margin-top:10px"><summary>More reflection · optional</summary><div class="fields" style="margin-top:10px">${field('What helped?','<textarea name="helped">'+esc(r.helped||'')+'</textarea>',1)}${field('What was hard?','<textarea name="hard">'+esc(r.hard||'')+'</textarea>',1)}</div></details><div class="form-actions"><button class="btn primary">🌙 ${r.id?'Update':'Save'} Day in Review</button></div></form></section></div>`}

function resetView(){return`<div class="page"><section class="hero"><div class="ey">🌸 RESET LAB</div><h2>I am not making another plan, I am changing state</h2><p>Pick one tiny state-change. You are allowed to stop after it.</p></section><section class="card full"><div class="button-row"><button class="btn primary" data-action="reset-log" data-label="Drink water">💧 Drink water</button><button class="btn" data-action="reset-log" data-label="Eat something">🍓 Eat something</button><button class="btn" data-action="reset-log" data-label="Stretch for five minutes">🌷 Stretch</button><button class="btn" data-action="reset-log" data-label="Five-minute tidy">🧺 Five-minute tidy</button><button class="btn dark" data-action="reset-log" data-label="Rest on purpose">🌙 Rest on purpose</button></div></section></div>`}
function patternsView(){const obs=list(state.insights.observations),patterns=list(state.profile?.patterns?.items||state.profile?.patterns||[]),exp=active('experiment',state.growth.experiments);return`<div class="page"><section class="hero"><div class="ey">🔬 PATTERN LAB</div><h2>Observations are not commandments</h2><p>Explicit rules outrank learned patterns. Nothing silently graduates into a rule.</p></section><div class="grid"><section class="card"><div class="ey">OBSERVATIONS</div><div class="stack">${obs.map((o,i)=>`<div class="row grow"><div>🔎</div><div><b>${esc(o.title||o.label||`Observation ${i+1}`)}</b><span class="meta">${esc(o.note||o.detail||'')}</span></div></div>`).join('')||'<div class="empty">No observations yet.</div>'}</div></section><section class="card"><div class="ey">EXPERIMENTS</div><div class="stack">${exp.map(e=>`<div class="row grow"><div>🔬</div><div><b>${esc(e.title)}</b><span class="meta">${list(e.attempts).length} attempts</span></div></div>`).join('')||'<div class="empty">No experiments.</div>'}</div></section></div></div>`}

function archiveRecord(a){const maps={task:state.life.tasks,reminder:state.life.reminders,routine:state.life.routines,event:state.life.events,thread:state.life.threads,food:state.nourish.noms.foods,recipe:state.nourish.noms.recipes,'motion-recipe':state.movement.routines,'motion-session':state.movement.sessions,'work-item':state.work.items,shift:state.work.shifts,training:state.work.training,career:state.work.career,bill:state.money.bills,debt:state.money.debts,course:state.education.courses,'study-item':state.education.items,goal:state.growth.goals,win:state.growth.wins,experiment:state.growth.experiments,person:state.v4.people,hobby:state.v4.hobbies,admin:state.v4.admin,wish:state.v4.shopping,dump:state.v4.brainDump};const r=list(maps[a.kind]).find(x=>String(x.id)===String(a.id));return r||null}
function recordTitle(kind,r){return r?.text||r?.title||r?.name||r?.label||`${kind} ${r?.id||''}`}
function archiveView(){const regs=list(state.v4.archive),reviews=list(state.insights.dayReviews).slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))),completedTasks=list(state.life.tasks).filter(x=>x.done);return`<div class="page"><section class="hero"><div class="ey">📦 MEMORY BOX</div><h2>Past things can leave the desk without disappearing</h2><p>Archive means hidden from active life. Delete means gone. Closed Drawer stays separate.</p></section><div class="grid"><section class="card full"><div class="ey">📦 ARCHIVED ON PURPOSE</div><div class="stack">${regs.map(a=>{const r=archiveRecord(a);return`<div class="row grow"><div>📦</div><div><b>${esc(recordTitle(a.kind,r))}</b><span class="meta">${esc(a.kind)} · archived ${new Date(a.archivedAt).toLocaleDateString()}</span></div><button class="btn tiny" data-action="restore" data-kind="${a.kind}" data-id="${a.id}">↩ Restore</button></div>`}).join('')||'<div class="empty">Nothing archived yet.</div>'}</div></section><section class="card"><div class="ey">🌙 DAY REVIEWS</div><div class="stack">${reviews.slice(0,20).map(r=>`<div class="row grow"><div>🌙</div><div><b>${fmtDate(r.date)}</b><span class="meta">${esc(r.mood||'no mood')} · ${esc(r.happened||r.proud||'review saved')}</span></div></div>`).join('')||'<div class="empty">No reviews yet.</div>'}</div></section><section class="card"><div class="ey">✓ COMPLETED SWEET TO-DOS</div><div class="stack">${completedTasks.slice().reverse().slice(0,20).map(t=>`<div class="row grow"><div>✓</div><div><b>${esc(t.text||t.title)}</b><span class="meta">${t.completedAt?new Date(t.completedAt).toLocaleDateString():''}</span></div></div>`).join('')||'<div class="empty">No completed tasks yet.</div>'}</div></section></div></div>`}

function settingsView(){return`<div class="page"><section class="hero"><div class="ey">🎀 V4 SETTINGS</div><h2>The “fuck no, I want V3 back” safety room</h2><p>V4 uses <b>sm_v4_beta</b>. V3 still uses <b>sm_v3_beta</b>. They are separate on purpose.</p></section><div class="grid"><section class="card"><div class="ey">V4 DATA</div><h2>Preview controls</h2><div class="button-row"><button class="btn" data-action="export-v4">Export V4 JSON</button><button class="btn danger" data-action="reset-v4">Reset V4 from current V3</button></div><div class="note" style="margin-top:10px">Reset V4 does not touch V3. It just throws away the V4 copy and re-imports the current V3 state.</div></section><section class="card"><div class="ey">V3 CODE DUNGEON</div><h2>Old tools remain available</h2><div class="footer-links"><a class="btn" href="../v3/">Open V3</a><a class="btn" href="../v3/control.html">Control Center</a><a class="btn" href="../v3/cloud.html">Cloud Nest</a><a class="btn" href="../v3/migrate.html">Migration Lab</a><a class="btn" href="../v3/launch.html">Launch Bay</a></div></section></div></div>`}

function renderDialog(){if(!dialog)return'';let body='';if(dialog.kind==='task'){const t=list(state.life.tasks).find(x=>x.id===dialog.id);if(t)body=`<form data-form="edit-task"><input type="hidden" name="id" value="${t.id}"><div class="fields">${field('Task',`<input name="text" value="${esc(t.text||t.title)}" required>`,1)}${field('Priority',`<select name="priority">${['today','soon','whenever','idea'].map(x=>`<option ${taskPriority(t)===x?'selected':''}>${x}</option>`).join('')}</select>`)}${field('Date',`<input name="date" type="date" value="${esc(t.date||'')}">`)}${field('Minutes',`<input name="minutes" type="number" value="${Number(t.minutes||15)}">`)}${field('Energy',`<select name="energy">${['low','medium','high'].map(x=>`<option ${t.energy===x?'selected':''}>${x}</option>`).join('')}</select>`)}${field('Location',`<input name="location" value="${esc(t.location||'')}">`)}${field('Protected',`<select name="protected"><option value="false" ${!t.protected?'selected':''}>Flexible</option><option value="true" ${t.protected?'selected':''}>Protected</option></select>`)}</div><div class="form-actions"><button class="btn primary">Save changes</button><button type="button" class="btn" data-action="close-dialog">Cancel</button></div></form>`}else if(dialog.kind==='reminder'){const r=list(state.life.reminders).find(x=>x.id===dialog.id);if(r)body=`<form data-form="edit-ping"><input type="hidden" name="id" value="${r.id}"><div class="fields">${field('Reminder',`<input name="title" value="${esc(r.title)}" required>`,1)}${field('Date',`<input name="date" type="date" value="${esc(r.date||'')}">`)}${field('Time',`<input name="time" type="time" value="${esc(r.time||'')}">`)}</div><div class="form-actions"><button class="btn primary">Save changes</button><button type="button" class="btn" data-action="close-dialog">Cancel</button></div></form>`}else if(dialog.kind==='debt'){const d=list(state.money.debts).find(x=>x.id===dialog.id);if(d)body=`<form data-form="edit-debt"><input type="hidden" name="id" value="${d.id}"><div class="fields">${field('Type',`<select name="type">${debtTypes.map(([v,l])=>`<option value="${v}" ${d.type===v?'selected':''}>${l}</option>`).join('')}</select>`)}${field('Name',`<input name="name" value="${esc(d.name)}">`)}${field('Balance',`<input name="balance" type="number" step=".01" value="${d.balance}">`)}${field('APR %',`<input name="apr" type="number" step=".01" value="${d.apr}">`)}${field('Payment',`<input name="paymentAmount" type="number" step=".01" value="${d.paymentAmount||d.minimum}">`)}${field('Due day',`<input name="dueDay" type="number" value="${d.dueDay||''}">`)}${field('Credit limit',`<input name="creditLimit" type="number" step=".01" value="${d.creditLimit||''}">`)}</div><div class="form-actions"><button class="btn primary">Save debt + linked bill</button><button type="button" class="btn" data-action="close-dialog">Cancel</button></div></form>`}else if(dialog.kind==='blocks')body=`<form data-form="blocks"><div class="note">One block per line: Name | HH:MM | HH:MM | low/okay/high/unknown</div>${field('Energy blocks',`<textarea name="blocks" style="min-height:180px">${esc(list(state.v4.energyBlocks).map(b=>`${b.name} | ${b.start} | ${b.end} | ${b.energy}`).join('\n'))}</textarea>`,1)}<div class="form-actions"><button class="btn primary">Save blocks</button><button type="button" class="btn" data-action="close-dialog">Cancel</button></div></form>`;return`<div class="dialog-backdrop"><div class="dialog"><h3>${dialog.kind==='blocks'?'🎀 Energy blocks':'✏️ Edit'}</h3>${body}</div></div>`}

function render(){let content='';const views={home:homeView,time:timeView,tasks:tasksView,mochini:mochiniView,pings:pingsView,routines:routinesView,noms:nomsView,sips:sipsView,motion:motionView,people:peopleView,hobbies:hobbiesView,boss:bossView,money:moneyView,study:studyView,threads:threadsView,growth:growthView,dump:dumpView,admin:adminView,review:reviewView,reset:resetView,patterns:patternsView,archive:archiveView,settings:settingsView};content=(views[view]||homeView)();app.className='';app.innerHTML=shell(content);requestAnimationFrame(()=>{const c=document.getElementById('conversation');if(c)c.scrollTop=c.scrollHeight})}

function formData(form){return Object.fromEntries(new FormData(form).entries())}
function bool(v){return String(v)==='true'}
function handleForm(form){const type=form.dataset.form,d=formData(form);if(type==='task'){state.life.tasks.push({id:makeId('task'),text:d.text,done:false,date:d.date,priority:d.priority,minutes:Number(d.minutes)||15,energy:d.energy,initiation:'easy',mode:'any',protected:bool(d.protected),location:d.location,createdAt:new Date().toISOString(),completedAt:'',source:'manual'});persist('Sweet To-Do added')}else if(type==='edit-task'){state.life.tasks=state.life.tasks.map(t=>t.id===d.id?{...t,text:d.text,date:d.date,priority:d.priority,minutes:Number(d.minutes)||15,energy:d.energy,location:d.location,protected:bool(d.protected)}:t);dialog=null;persist('Task updated')}else if(type==='ping'){state.life.reminders.push({id:makeId('ping'),title:d.title,date:d.date,time:d.time,timing:d.timing,completed:false,createdAt:new Date().toISOString(),source:'manual'});persist('Little Ping added')}else if(type==='edit-ping'){state.life.reminders=state.life.reminders.map(r=>r.id===d.id?{...r,title:d.title,date:d.date,time:d.time}:r);dialog=null;persist('Little Ping updated')}else if(type==='event'){state.life.events.push({id:makeId('event'),title:d.title,type:d.type,date:d.date,startTime:d.startTime,endTime:d.endTime,location:d.location,createdAt:new Date().toISOString()});persist('Berry Busy item added')}else if(type==='mochini'){const result=processMochini(state,d.message);state=result.state;state=saveState(state);render()}else if(type==='routine'){const steps=text(d.steps).split('\n').map((label,i)=>({id:makeId(`step${i}`),label:text(label),minutes:5,optional:false})).filter(x=>x.label);state.life.routines.push({id:makeId('routine'),name:d.name,icon:d.icon||'🎀',daypart:d.daypart,recurrence:d.recurrence,days:[],steps,archived:false,createdAt:new Date().toISOString()});persist('Routine added')}else if(type==='food'){state.nourish.noms.foods.push({id:makeId('food'),name:d.name,kind:'other',tags:[],effort:'low',prepMinutes:0,available:Number(d.quantity)>0,trackQuantity:true,quantity:Math.max(0,Number(d.quantity)||0),lowAt:Math.max(0,Number(d.lowAt)||1),createdAt:new Date().toISOString()});persist('Stocked Nom added')}else if(type==='grocery'){state.nourish.noms.groceries=[...list(state.nourish.noms.groceries),{id:makeId('grocery'),name:d.name,quantity:d.quantity,checked:false,createdAt:new Date().toISOString()}];persist('Added to grocery basket')}else if(type==='meal'){state.nourish.noms.mealPlan=[...list(state.nourish.noms.mealPlan),{id:makeId('meal'),label:d.label,date:d.date,slot:d.slot,sourceType:'manual',createdAt:new Date().toISOString()}];persist('Nom planned')}else if(type==='recipe'){state.nourish.noms.recipes=[...list(state.nourish.noms.recipes),{id:makeId('recipe'),name:d.name,prepMinutes:Number(d.prepMinutes)||15,ingredients:text(d.ingredients).split(',').map(text).filter(Boolean),available:true,createdAt:new Date().toISOString()}];persist('Recipe saved')}else if(type==='nom-log'){state.nourish.noms.history.push({id:makeId('nom-log'),name:d.name,sourceType:'manual',sourceId:'',kind:'other',date:today(),loggedAt:new Date().toISOString()});persist('Nom logged')}else if(type==='sip'){state.nourish.sips.waterGoalOz=Math.max(8,Number(d.goal)||64);state.nourish.sips.history.push({id:makeId('sip'),name:d.name||d.type,ounces:Number(d.ounces)||0,type:d.type,date:today(),loggedAt:new Date().toISOString(),source:'manual'});persist('Sip logged')}else if(type==='motion'){state.movement.sessions.push({id:makeId('motion'),type:d.type,label:d.type[0].toUpperCase()+d.type.slice(1),minutes:Number(d.minutes)||0,effort:d.effort,date:d.date,loggedAt:new Date().toISOString(),source:'manual'});persist('Movement logged')}else if(type==='person'){state.v4.people.push({id:makeId('person'),name:d.name,relationship:d.relationship,likes:d.likes,importantDates:d.importantDates,giftIdeas:d.giftIdeas,createdAt:new Date().toISOString()});persist('Person added')}else if(type==='hobby'){state.v4.hobbies.push({id:makeId('hobby'),name:d.name,status:d.status,kind:d.kind,language:bool(d.language),notes:d.notes,lastTouched:'',createdAt:new Date().toISOString()});persist('Hobby added')}else if(type==='work-item'){state.work.items.push({id:makeId('work-item'),text:d.text,dueDate:d.dueDate,minutes:Number(d.minutes)||15,done:false,protected:bool(d.protected),createdAt:new Date().toISOString()});persist('Work item added')}else if(type==='shift'){state.work.shifts.push({id:makeId('shift'),label:d.label||'Work shift',date:d.date,startTime:d.startTime,endTime:d.endTime,status:'planned',createdAt:new Date().toISOString()});persist('Shift added')}else if(type==='bill'){state.money.bills.push({id:makeId('bill'),name:d.name,amount:Number(d.amount)||0,dueDate:d.dueDate,dueDay:Number(d.dueDay)||0,recurring:true,paid:false,createdAt:new Date().toISOString()});persist('Bill added')}else if(type==='debt'){state=upsertDebt(state,{type:d.type,name:d.name,balance:d.balance,apr:d.apr,paymentAmount:d.paymentAmount,minimum:d.paymentAmount,dueDay:d.dueDay,creditLimit:d.creditLimit,lender:d.lender});persist('Debt added and linked bill created')}else if(type==='edit-debt'){state=upsertDebt(state,{id:d.id,type:d.type,name:d.name,balance:d.balance,apr:d.apr,paymentAmount:d.paymentAmount,minimum:d.paymentAmount,dueDay:d.dueDay,creditLimit:d.creditLimit});dialog=null;persist('Debt and linked bill updated')}else if(type==='earning'){state.money.earnings.push({id:makeId('earning'),kind:'paycheck',label:d.label,status:d.status,expectedDate:d.date,receivedDate:d.status==='received'?d.date:'',estimatedGross:Number(d.amount)||0,receivedAmount:d.status==='received'?Number(d.amount)||0:0,createdAt:new Date().toISOString()});persist('Income added')}else if(type==='savings'){state.money.savingsGoals.push({id:makeId('savings'),name:d.name,current:Number(d.current)||0,target:Number(d.target)||0,createdAt:new Date().toISOString()});persist('Savings goal added')}else if(type==='spending'){state.money.spending.push({id:makeId('spend'),description:d.description,amount:Number(d.amount)||0,category:d.category,date:d.date,loggedAt:new Date().toISOString(),source:'manual'});persist('Spending logged')}else if(type==='wish'){state.v4.shopping.push({id:makeId('wish'),name:d.name,price:Number(d.price)||0,category:d.category,why:d.why,waitUntil:d.waitUntil,bought:false,createdAt:new Date().toISOString()});persist('Added to wishlist')}else if(type==='course'){state.education.courses.push({id:makeId('course'),title:d.title,progress:Number(d.progress)||0,currentObjective:d.currentObjective,nextMilestone:d.nextMilestone,targetDate:d.targetDate,status:'active',createdAt:new Date().toISOString()});persist('Course added')}else if(type==='study-item'){state.education.items.push({id:makeId('study-item'),courseId:d.courseId,title:d.title,type:'study',dueDate:d.dueDate,minutes:Number(d.minutes)||15,energy:'medium',initiation:'easy',difficulty:'medium',protected:false,done:false,createdAt:new Date().toISOString()});persist('Study item added')}else if(type==='study-session'){state.education.sessions.push({id:makeId('study-session'),courseId:d.courseId,date:d.date,minutes:Number(d.minutes)||0,completedAt:new Date().toISOString()});persist('Study session logged')}else if(type==='thread'){state.life.threads.push({id:makeId('thread'),title:d.title,icon:'🧵',summary:d.summary,status:d.status,deadline:d.deadline,notes:[],resources:[],links:{},createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});persist('Thread started')}else if(type==='goal'){state.growth.goals.push({id:makeId('goal'),title:d.title,why:d.why,targetDate:d.targetDate,status:'moving',kind:'outcome',milestones:[],createdAt:new Date().toISOString()});persist('Goal added')}else if(type==='win'){state.growth.wins.push({id:makeId('win'),title:d.title,note:d.note,date:today(),source:'manual',createdAt:new Date().toISOString()});persist('Win saved')}else if(type==='dump'){state.v4.brainDump.push({id:makeId('dump'),text:d.text,bucket:d.bucket,createdAt:new Date().toISOString()});persist(d.bucket==='closed'?'Locked in Closed Drawer':'Brain dump saved')}else if(type==='admin'){state.v4.admin.push({id:makeId('admin'),name:d.name,kind:d.kind,physicalLocation:d.physicalLocation,digitalLocation:d.digitalLocation,expires:d.expires,notes:d.notes,createdAt:new Date().toISOString()});persist('Life-admin record saved')}else if(type==='review'){const existing=list(state.insights.dayReviews).find(x=>x.date===today()),r={...existing,id:existing?.id||makeId('review'),date:today(),mood:d.mood,energy:d.energy,happened:d.happened,proud:d.proud,tomorrow:d.tomorrow,helped:d.helped,hard:d.hard,snapshot:reviewSnapshot(today()),createdAt:existing?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};state.insights.dayReviews=[...list(state.insights.dayReviews).filter(x=>x.date!==today()),r];persist('Day in Review saved')}else if(type==='blocks'){const blocks=text(d.blocks).split('\n').map((line,i)=>{const [name,start,end,energy]=line.split('|').map(text);return{id:makeId(`block${i}`),name:name||`Block ${i+1}`,start,end,energy:['low','okay','high','unknown'].includes(energy)?energy:'okay'}}).filter(x=>x.start&&x.end);state.v4.energyBlocks=blocks;dialog=null;persist('Energy blocks updated')}}

function approveProposal(){const p=state.mochini?.pendingProposal;if(!p)return;if(p.kind==='task'){state.life.tasks.push({id:makeId('task'),...p.payload,priority:p.payload.date===today()?'today':'whenever',done:false,createdAt:new Date().toISOString(),source:'mochini'})}else if(p.kind==='reminder'){state.life.reminders.push({id:makeId('ping'),...p.payload,completed:false,createdAt:new Date().toISOString(),source:'mochini'})}else if(p.kind==='task-batch'){for(const item of p.payload.items)state.life.tasks.push({id:makeId('task'),...item,priority:item.date===today()?'today':'whenever',done:false,createdAt:new Date().toISOString(),source:'mochini'})}state.mochini.pendingProposal=null;state.mochini.conversation.push({id:makeId('turn'),role:'assistant',text:'Done 😊 It’s in the right room now.',at:new Date().toISOString()});persist('Mochini action approved')}

function deleteByKind(kind,id){if(kind==='task')state.life.tasks=state.life.tasks.filter(x=>x.id!==id);else if(kind==='reminder')state.life.reminders=state.life.reminders.filter(x=>x.id!==id);else if(kind==='debt'){state=removeDebt(state,id)}else if(kind==='person')state.v4.people=state.v4.people.filter(x=>x.id!==id);else if(kind==='nom-log')state.nourish.noms.history=state.nourish.noms.history.filter(x=>x.id!==id);else if(kind==='sip')state.nourish.sips.history=state.nourish.sips.history.filter(x=>x.id!==id);else if(kind==='motion-session')state.movement.sessions=state.movement.sessions.filter(x=>x.id!==id);else if(kind==='grocery')state.nourish.noms.groceries=state.nourish.noms.groceries.filter(x=>x.id!==id);persist('Deleted')}

document.addEventListener('click',e=>{const v=e.target.closest('[data-view]');if(v){setView(v.dataset.view);return}const mode=e.target.closest('[data-mode]');if(mode){setMode(mode.dataset.mode);return}const tab=e.target.closest('[data-noms-tab]');if(tab){state.v4.ui.nomsTab=tab.dataset.nomsTab;state=saveState(state);render();return}const mt=e.target.closest('[data-money-tab]');if(mt){state.v4.ui.moneyTab=mt.dataset.moneyTab;state=saveState(state);render();return}const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action,id=a.dataset.id,kind=a.dataset.kind;if(action==='menu')document.getElementById('sidebar')?.classList.toggle('open');else if(action==='archive'){state=archiveItem(state,kind,id);persist('Archived to Memory Box')}else if(action==='restore'){state=restoreItem(state,kind,id);persist('Restored')}else if(action==='delete'){if(confirm('Delete this for real? Archive is safer if you just want it off the desk.'))deleteByKind(kind,id)}else if(action==='edit'){dialog={kind,id};render()}else if(action==='close-dialog'){dialog=null;render()}else if(action==='edit-blocks'){dialog={kind:'blocks'};render()}else if(action==='toggle-task'){state.life.tasks=state.life.tasks.map(t=>t.id===id?{...t,done:!t.done,completedAt:!t.done?new Date().toISOString():''}:t);persist('Task updated')}else if(action==='toggle-ping'){state.life.reminders=state.life.reminders.map(r=>r.id===id?{...r,completed:!r.completed,completedAt:!r.completed?new Date().toISOString():''}:r);persist('Ping updated')}else if(action==='open-plan')makeOpenDayPlan(a.dataset.date);else if(action==='approve-proposal')approveProposal();else if(action==='reject-proposal'){state=rejectProposal(state);persist('Proposal cleared')}else if(action==='clarify'){state=resolveClarification(state,a.dataset.target);state=saveState(state);render()}else if(action==='clear-chat'){state=clearChat(state);persist('Chat cleared')}else if(action==='routine-step'){const r=state.life.routines.find(x=>x.id===a.dataset.routine),inst=routineInstance(r);inst.stepStates={...inst.stepStates,[a.dataset.step]:!inst.stepStates?.[a.dataset.step]};const all=list(r.steps).length&&list(r.steps).every(s=>inst.stepStates[s.id]);inst.status=all?'completed':'active';inst.updatedAt=new Date().toISOString();persist('Routine progress saved')}else if(action==='routine-finish'){const r=state.life.routines.find(x=>x.id===id),inst=routineInstance(r);inst.stepStates=Object.fromEntries(list(r.steps).map(s=>[s.id,true]));inst.status='completed';persist('Routine finished ✨')}else if(action==='routine-skip'){const inst=routineInstance(state.life.routines.find(x=>x.id===id));inst.status='skipped';persist('Skipped today with no guilt math')}else if(action==='routine-defer'){const inst=routineInstance(state.life.routines.find(x=>x.id===id));inst.status='deferred';persist('Deferred today')}else if(action==='routine-reactivate'){const inst=routineInstance(state.life.routines.find(x=>x.id===id));inst.status='active';persist('Routine brought back')}else if(action==='save-stock'){const f=state.nourish.noms.foods.find(x=>x.id===id),q=document.querySelector(`[data-stock-qty="${CSS.escape(id)}"]`),l=document.querySelector(`[data-stock-low="${CSS.escape(id)}"]`);if(f){f.trackQuantity=true;f.quantity=Math.max(0,Number(q?.value)||0);f.lowAt=Math.max(0,Number(l?.value)||1);f.available=f.quantity>0;persist('Stock saved in place')}}else if(action==='log-nom'){const f=state.nourish.noms.foods.find(x=>x.id===id);if(f){state.nourish.noms.history.push({id:makeId('nom-log'),name:f.name,sourceType:'food',sourceId:f.id,kind:f.kind||'other',date:today(),loggedAt:new Date().toISOString()});if(f.trackQuantity===true||f.quantity!==undefined){f.trackQuantity=true;f.quantity=Math.max(0,Number(f.quantity||0)-1);f.available=f.quantity>0}persist(`${f.name} logged`)}}else if(action==='grocery-toggle'){state.nourish.noms.groceries=state.nourish.noms.groceries.map(g=>g.id===id?{...g,checked:!g.checked}:g);persist('Basket updated')}else if(action==='motion-recipe-log'){const r=state.movement.routines.find(x=>x.id===id);if(r){state.movement.sessions.push({id:makeId('motion'),type:r.type,label:r.name,minutes:r.minutes,effort:r.effort,date:today(),loggedAt:new Date().toISOString(),recipeId:r.id});persist('Movement logged')}}else if(action==='touch-hobby'){state.v4.hobbies=state.v4.hobbies.map(h=>h.id===id?{...h,lastTouched:today()}:h);persist('Hobby touched ✨')}else if(action==='toggle-work'){state.work.items=state.work.items.map(x=>x.id===id?{...x,done:!x.done}:x);persist('Work queue updated')}else if(action==='focus-start'){state.work.focus={active:true,label:'Boss Bitch focus',minutes:25,startedAt:new Date().toISOString(),endsAt:new Date(Date.now()+25*60000).toISOString()};persist('Focus sprint started')}else if(action==='focus-stop'){state.work.focus={};persist('Focus sprint stopped')}else if(action==='bill-paid'){state.money.bills=state.money.bills.map(b=>b.id===id?{...b,paid:!b.paid}:b);persist('Bill status updated')}else if(action==='toggle-study'){state.education.items=state.education.items.map(i=>i.id===id?{...i,done:!i.done,completedAt:!i.done?new Date().toISOString():''}:i);persist('Study item updated')}else if(action==='thread-status'){state.life.threads=state.life.threads.map(t=>t.id===id?{...t,status:a.dataset.status,updatedAt:new Date().toISOString()}:t);persist('Thread updated')}else if(action==='reset-log'){state.insights.resetSessions=[...list(state.insights.resetSessions),{id:makeId('reset'),label:a.dataset.label,date:today(),completedAt:new Date().toISOString()}];persist(`${a.dataset.label} counts`)}else if(action==='export-v4'){const blob=new Blob([JSON.stringify({data:state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`KatOS-V4-${today()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),500)}else if(action==='reset-v4'){if(confirm('Throw away the V4 copy and rebuild it from current V3? V3 itself will NOT change.')){state=resetV4FromV3();view='home';render()}}});

document.addEventListener('submit',e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();handleForm(form)});
window.addEventListener('storage',e=>{if(e.key==='sm_v4_beta'){state=loadState();render()}});
render();
